df = pd.DataFrame(data)

import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns

clean_df = df.replace(r"^\s*$", np.nan, regex=True)

completion_pct = (clean_df.notna().mean() * 100).reset_index()
completion_pct.columns = ["column", "non_null_percentage"]

plt.figure(figsize=(8, 4.5))
ax = sns.barplot(
    data=completion_pct,
    x="non_null_percentage",
    y="column",
    color="steelblue",
)

ax.set_xlim(0, 100)
ax.set_xlabel("Completion Rate (%)")
ax.set_ylabel("Columns")
ax.set_title("Percentage of Valid (Non-Empty / Non-Null) Data by Column")

for p in ax.patches:
    width = p.get_width()
    ax.annotate(
        f"{width:.1f}%",
        (width, p.get_y() + p.get_height() / 2.0),
        xytext=(5, 0),
        textcoords="offset points",
        va="center",
        fontsize=10,
    )

sns.despine(left=True, bottom=False)
plt.tight_layout()
plt.show()